    var doc=null;
    try{ doc=CT_CREATE.songOf(code); }catch(e){ doc=null; }
    if(!doc) return null;
    _sharedTitle=doc.title||'';
    // NOT the deck token: a document has none, and returning '' made every
    // successful call read as a failure to the caller that had to decide
