    if(!cs){ _autoRetryAt=(ctx?ctx.currentTime:0)+5; return null; }
    if(ctx && started){
      Engine.killAll(opts.fade!=null?opts.fade:0.12);
      Engine.clearFuture(ctx.currentTime+0.02);
    }
