    deckCur=d; deckNext=null;
    // A live join starts mid-track; the chip skips to the same frame.
    gbPlay(cs.score, Math.round(off*(typeof CT_GB_HARDWARE!=='undefined'?CT_GB_HARDWARE.FPS:59.7275)), transportPaused, 0.18);
