    if(slot - _lastSfxSlot < step16*0.5){ bump(0.012); return; }   // at most ONE sfx note per slot
    _lastSfxSlot = slot;
    const fr = pitchFreq(mtof(nextMelodyMidi() + (semis||0)));     // the next melody note, in key
