/* ===== src/packs.js ===== */
// Fixed bundled product roster. Chiptunes is not a plug-in host: games and the
// single composer are loaded by build.js before runtime.js.
(function(){
'use strict';
var listeners=[];
function games(){
  var map=window.CT_GAMES||{};
  return Object.keys(map).sort().map(function(id){
    var game=map[id]||{};
    return {id:id,kind:'game',name:game.name||id,version:'bundled',enabled:true,loaded:true,
      manifest:{id:id,kind:'game',name:game.name||id,version:'bundled'}};
  });
}
function get(id){
  var game=(window.CT_GAMES||{})[id];
  if(!game)return null;
  var info=games().filter(function(row){return row.id===id;})[0];
  return Object.assign({},info,{loadGame:function(){return Promise.resolve(game);}});
}
window.activeComposer=function(){
  return window.CT_COMPOSERS&&window.CT_COMPOSERS.rrr_core;
};
window.Packs={
  init:function(){return Promise.resolve(games());},
  list:games,
  get:get,
  onChange:function(fn){if(typeof fn==='function')listeners.push(fn);return function(){
    listeners=listeners.filter(function(x){return x!==fn;});
  };},
  activeComposerId:function(){return 'rrr_core';}
};
})();

/* ===== packs/games/hover/definition.js ===== */
// HOVER FIGHT pack definition. Owns nouns, rules, collision, and progress.
(function(){
  const H = VisualizerGame.helpers;
  const W = 256, HGT = 224;
  // '#54fc54' (green) is RESERVED for the PLAYER's hovers (rendered in renderer.js). EVERY other hover in the
  // game — enemies and floating collectibles alike — draws from this green-free pool, so green on screen always
  // means "that's the player". (The renderer also draws enemy + player hovers UNROTATED for the same reason:
  // hue-rotating them slid the player off green and swept others onto it.)
  const HOVER_COLORS = ['#fc5454','#3cbcfc','#fcfc54','#fc54fc','#54fcfc'];
  const ENEMY_HOVER_COLORS = HOVER_COLORS;
  const SLOT_Y = [44, 62, 82, 104, 126, 148];

  function viewportWidth(area){
    return Math.max(W, Math.round(HGT * ((area && area.w) || W) / Math.max(1, (area && area.h) || HGT)));
  }

  function rootObj(){
    return typeof window !== 'undefined' ? window : globalThis;
  }
  function clamp(v, lo, hi){ return H.clamp(v, lo, hi); }
  function box(o){
    return { x:o.x - (o.w || 10) / 2, y:o.y - (o.h || 10) / 2, w:o.w || 10, h:o.h || 10 };
  }
  function emit(ctx, type, detail){
    if(ctx && typeof ctx.emit === 'function') ctx.emit(type, detail || null);
  }
  function addBurst(st, x, y, col, n){
    n = Math.min(10, n || 5);
    for(let i=0;i<n && st.effects.length<96;i++){
      const a = st.rng.range(0, Math.PI * 2);
      st.effects.push({
        x, y, vx:Math.cos(a) * st.rng.range(14, 58), vy:Math.sin(a) * st.rng.range(12, 48),
        ttl:st.rng.range(0.22, 0.55), age:0, col:col || '#ffffff', size:st.rng.range(1, 2.8)
      });
    }
  }
  function resetPlayer(st, x){
    st.player.x = x == null ? st.cameraX + 62 : x;
    st.player.y = 68;
    st.player.vx = 18;
    st.player.vy = -12;
    st.player.hovers = Math.max(1, st.player.hovers || 2);
    st.player.inv = 1.2;
    st.player.state = 'fly';
    st.player.flapGap = 0;
  }
  function spawnStars(st){
    st.stars.length = 0;
    const count = Math.max(26, Math.ceil(26 * st.nativeW / W));
    for(let i=0;i<count;i++){
      st.stars.push({
        x:st.rng.range(0, st.nativeW),
        y:st.rng.range(10, 150),
        phase:st.rng.range(0, Math.PI * 2),
        size:st.rng.range(0.6, 1.6),
        twinkle:st.rng.range(0.6, 1.8)
      });
    }
  }
  function platform(x, y, w){
    return { x, y, w, h:8, type:'platform', alive:true };
  }
  function makeEnemy(st, x, y, i){
    return {
      id:'enemy-' + i,
      type:'enemy',
      x, y, w:13, h:22,
      vx:st.rng.range(-18, 18),
      vy:st.rng.range(-8, 8),
      face:1,
      hovers:2,
      phase:st.rng.range(0, Math.PI * 2),
      col:ENEMY_HOVER_COLORS[(i + 1) % ENEMY_HOVER_COLORS.length],
      alive:true,
      hit:0
    };
  }
  function setupFight(st){
    const vw = st.nativeW || W;
    const span = vw / W;
    st.mode = 'fight';
    st.cameraX = 0;
    st.worldX = 0;
    st.frontier = vw;
    st.stageLength = vw;
    st.platforms = [];
    st.collectibles.length = 0;
    st.hazards.length = 0;
    st.enemies.length = 0;
    const platformCount = Math.max(4, Math.ceil(4 * span));
    for(let i=0;i<platformCount;i++){
      const band = (i + 0.5) / platformCount;
      st.platforms.push(platform(band * vw + st.rng.range(-10, 10), 76 + (i % 4) * 23, 40 + st.rng.range(0, 10)));
    }
    const enemyCount = Math.max(6, Math.ceil(6 * span));
    const enemyCols = Math.max(3, Math.ceil(enemyCount / 2));
    for(let i=0;i<enemyCount;i++){
      st.enemies.push(makeEnemy(st, (i % enemyCols + 0.5) * vw / enemyCols + st.rng.range(-10, 10), 44 + Math.floor(i / enemyCols) * 46, i));
    }
    const collectibleCount = Math.max(7, Math.ceil(7 * span));
    for(let i=0;i<collectibleCount;i++){
      addCollectible(st, (i + 0.6) * vw / collectibleCount, 42 + Math.sin(i * 0.8) * 20 + (i % 2) * 18, HOVER_COLORS[i % HOVER_COLORS.length], i / Math.max(1, collectibleCount - 1), 0.55);
    }
    const hazardCount = Math.max(2, Math.ceil(2 * span));
    for(let i=0;i<hazardCount;i++) addHazard(st, (i + 0.75) * vw / hazardCount, i % 2 ? 72 : 118);
    st.fish = { x:vw * 0.5, y:st.waterY + 28, vy:0, active:false, phase:0, alive:true };
    resetPlayer(st, Math.min(70, vw * 0.22));
  }
  function setupTrip(st){
    st.mode = 'trip';
    st.worldX = 0;
    st.cameraX = 0;
    st.frontier = 190;
    st.stageLength = 2500 + st.rng.int(0, 5) * 180;
    st.platforms.length = 0;
    st.enemies.length = 0;
    st.collectibles.length = 0;
    st.hazards.length = 0;
    st.fish = { x:st.nativeW * 0.5, y:st.waterY + 28, vy:0, active:false, phase:0, alive:true };
    resetPlayer(st, 58);
    while(st.frontier < st.nativeW + 604) spawnTripCluster(st);
  }

  function configureLayout(st, area){
    const nextW = viewportWidth(area);
    if(nextW === st.nativeW) return;
    st.nativeW = nextW;
    spawnStars(st);
    if(st.mode === 'fight') setupFight(st);
    else {
      while(st.frontier < st.cameraX + nextW + 364 && st.frontier < st.stageLength + 380) spawnTripCluster(st);
      st.player.x = clamp(st.player.x, st.cameraX + 22, st.cameraX + nextW - 58);
      if(st.fish) st.fish.x = nextW * 0.5;
    }
  }
  function chooseNextMode(st, from){
    if(from === 'trip') setupFight(st);
    else setupTrip(st);
    st.stage++;
  }
  function addCollectible(st, x, y, col, pitch, strength){
    st.collectibles.push({
      id:'hover-' + st.nextId++,
      type:'collectible',
      x, y, baseY:y,
      w:12, h:16,
      col,
      pitch:pitch || 0.5,
      strength:strength || 0.4,
      phase:st.rng.range(0, Math.PI * 2),
      got:false,
      pulse:0
    });
  }
  function addHazard(st, x, y){
    st.hazards.push({
      id:'bomb-' + st.nextId++,
      type:'bomb',
      x, y, baseY:y,
      w:12, h:12,
      phase:st.rng.range(0, Math.PI * 2),
      pulse:0,
      alive:true
    });
  }
  function spawnTripCluster(st){
    const music = st.music || {};
    const idx = st.clusterIndex++;
    const energy = clamp(music.energy == null ? 0.35 : music.energy, 0, 1);
    const pitch = clamp(music.leadHi == null ? st.rng.range(0.2, 0.8) : music.leadHi, 0, 1);
    const slot = clamp(Math.round((1 - pitch) * (SLOT_Y.length - 1)) + st.rng.int(-1, 1), 0, SLOT_Y.length - 1);
    const baseY = SLOT_Y[slot];
    const count = 6 + Math.round(energy * 7) + st.rng.int(0, 2);
    const dx = 18 + st.rng.range(0, 5);
    const pattern = idx % 5;
    const dir = idx % 2 ? 1 : -1;
    const x0 = st.frontier + st.rng.range(8, 26);
    const col = HOVER_COLORS[(idx + Math.round(pitch * 5)) % HOVER_COLORS.length];
    for(let i=0;i<count;i++){
      let y = baseY;
      if(pattern === 1) y += Math.sin(i * 0.65) * 11;
      else if(pattern === 2) y += dir * i * 3.5;
      else if(pattern === 3) y -= Math.sin(i / Math.max(1, count - 1) * Math.PI) * 18 * dir;
      else if(pattern === 4) y += (i % 2 ? 7 : -7);
      addCollectible(st, x0 + i * dx, clamp(y, 32, st.waterY - 34), col, pitch, 0.45 + energy * 0.45);
    }
    const hazardLane = clamp(baseY + (baseY < 92 ? 55 : -50) + st.rng.range(-10, 10), 38, st.waterY - 28);
    if(st.rng.chance(0.35 + energy * 0.35)){
      const n = 2 + Math.round(energy * 3);
      for(let i=0;i<n;i++) addHazard(st, x0 + dx * (1.2 + i * 2.2), hazardLane + Math.sin(i) * 9);
    }
    st.frontier = x0 + count * dx + 90 + st.rng.range(0, 80);
  }
  function updateEffects(st, dt){
    for(let i=st.effects.length-1;i>=0;i--){
      const e = st.effects[i];
      e.age += dt;
      e.x += e.vx * dt;
      e.y += e.vy * dt;
      e.vy += 38 * dt;
      if(e.age >= e.ttl) st.effects.splice(i, 1);
    }
  }
  function updateFish(ctx, dt){
    const st = ctx.state, p = st.player, fish = st.fish;
    if(!fish) return;
    fish.phase += dt * (1.5 + (st.music ? st.music.bass : 0));
    const dx = p.x - (st.cameraX + fish.x);
    if(!fish.active && Math.abs(dx) < 36 && p.y > st.waterY - 48 && st.rng.chance(0.018 + (st.music ? st.music.bass * 0.04 : 0))){
      fish.active = true;
      fish.x = p.x - st.cameraX;
      fish.y = st.waterY + 24;
      fish.vy = -118;
      emit(ctx, 'fishLunged', { x:p.x, y:p.y });
    }
    if(fish.active){
      fish.y += fish.vy * dt;
      fish.vy += 150 * dt;
      if(fish.y > st.waterY + 26) fish.active = false;
      if(Math.abs((st.cameraX + fish.x) - p.x) < 15 && Math.abs(fish.y - p.y) < 18 && p.inv <= 0){
        p.hovers = Math.max(0, p.hovers - 1);
        p.inv = 1.1;
        addBurst(st, p.x, p.y, '#54fcfc', 8);
        emit(ctx, 'pop', { source:'fish' });
      }
    }
  }
  function playerPhysics(ctx, dt){
    const st = ctx.state, p = st.player, input = ctx.IN || {}, intent = st.intent || {};
    const music = st.music || {};
    const manual = !!input.active;
    let steer = manual ? ((input.right?1:0) - (input.left?1:0)) : (intent.steer || 0);
    let wantsFlap = manual ? !!(input.up || input.action) : !!intent.flap;
    p.inv = Math.max(0, p.inv - dt);
    p.flapGap = Math.max(0, p.flapGap - dt);
    p.vx += steer * 94 * dt;
    p.vx *= Math.pow(0.08, dt);
    p.vx = clamp(p.vx, -54, 68);
    if(wantsFlap && p.flapGap <= 0){
      p.vy -= 74 + (p.hovers > 1 ? 14 : 0);
      p.flap = 1;
      p.flapGap = 0.16;
      emit(ctx, 'flap', { x:p.x, y:p.y });
    }
    p.flap = Math.max(0, p.flap - dt * 6);
    p.vy += (86 - (p.hovers > 1 ? 14 : 0)) * dt;
    p.vy -= (music.beat || 0) * 10 * dt;
    p.vy *= Math.pow(0.18, dt);
    p.x += p.vx * dt;
    p.y += p.vy * dt;
    if(st.mode === 'trip'){
      const minX = st.cameraX + 22, maxX = st.cameraX + st.nativeW - 58;
      if(p.x < minX){ p.x = minX; p.vx = Math.max(8, p.vx); }
      if(p.x > maxX){ p.x = maxX; p.vx = Math.min(-6, p.vx); }
    } else {
      if(p.x < 18){ p.x = 18; p.vx = Math.max(0, p.vx); }
      if(p.x > st.nativeW - 18){ p.x = st.nativeW - 18; p.vx = Math.min(0, p.vx); }
    }
    if(p.y < 20){ p.y = 20; p.vy = Math.max(6, p.vy); }
    if(p.y > st.waterY - 12){
      addBurst(st, p.x, st.waterY, '#54fcfc', 10);
      emit(ctx, 'splash', { x:p.x, y:st.waterY });
      resetPlayer(st, st.mode === 'trip' ? st.cameraX + 56 : 70);
    }
  }
  function updateTrip(ctx, dt){
    const st = ctx.state;
    const music = st.music || {};
    const tempo = clamp((music.bpm || 132) / 132, 0.65, 1.85);
    const speed = (46 + (music.energy || 0.35) * 28) * tempo;
    st.worldX += speed * dt;
    st.cameraX = st.worldX;
    while(st.frontier < st.worldX + st.nativeW + 364 && st.frontier < st.stageLength + 380) spawnTripCluster(st);
    for(let i=st.collectibles.length-1;i>=0;i--){
      const b = st.collectibles[i];
      b.pulse = Math.max(0, b.pulse - dt * 4);
      b.y = b.baseY + Math.sin(st.t * 3.2 + b.phase) * (1.6 + (music.leadEnergy || 0) * 3);
      if(b.x < st.cameraX - 90 || b.got) st.collectibles.splice(i, 1);
    }
    for(let i=st.hazards.length-1;i>=0;i--){
      const h = st.hazards[i];
      h.pulse = Math.max(0, h.pulse - dt * 4);
      h.y = h.baseY + Math.sin(st.t * 3.8 + h.phase) * (2 + (music.percEnergy || 0) * 4);
      if(h.x < st.cameraX - 90 || !h.alive) st.hazards.splice(i, 1);
    }
    if(st.worldX > st.stageLength){
      emit(ctx, 'levelComplete', { mode:'trip', stage:st.stage });
      chooseNextMode(st, 'trip');
    }
  }
  function updateFight(ctx, dt){
    const st = ctx.state, p = st.player, music = st.music || {};
    let alive = 0;
    for(let i=0;i<st.enemies.length;i++){
      const e = st.enemies[i];
      if(!e.alive) continue;
      alive++;
      e.hit = Math.max(0, e.hit - dt * 5);
      e.phase += dt * 3;
      const away = Math.abs(e.x - p.x) < 28 && Math.abs(e.y - p.y) < 24 ? (e.x < p.x ? -1 : 1) : 0;
      e.vx += (away * 40 + Math.sin(st.t * 0.9 + i) * 14) * dt;
      e.vx = clamp(e.vx, -34, 34);
      e.vy += (Math.sin(st.t * 1.4 + i * 1.7) * 25 - 6 - (music.counterEnergy || 0) * 12) * dt;
      e.vy += 52 * dt;
      e.vy = clamp(e.vy, -40, 38);
      e.x += e.vx * dt;
      e.y += e.vy * dt;
      if(e.x < 18 || e.x > st.nativeW - 18){ e.vx *= -1; e.x = clamp(e.x, 18, st.nativeW - 18); }
      if(e.y < 26){ e.y = 26; e.vy = 10; }
      if(e.y > st.waterY - 16){ e.y = st.waterY - 16; e.vy = -34; }
      e.face = e.vx >= 0 ? 1 : -1;
    }
    if(alive <= 0){
      emit(ctx, 'levelComplete', { mode:'fight', stage:st.stage });
      chooseNextMode(st, 'fight');
    }
  }
  function collisions(ctx){
    const st = ctx.state, p = st.player, pr = box(p);
    for(let i=0;i<st.collectibles.length;i++){
      const b = st.collectibles[i];
      if(b.got) continue;
      if(H.rectsOverlap(pr, box(b))){
        b.got = true;
        p.hovers = Math.min(3, p.hovers + 0.15);
        st.score += 50;
        addBurst(st, b.x, b.y, b.col, 6);
        emit(ctx, 'hoverCollected', { x:b.x, y:b.y, score:st.score });
      }
    }
    for(let i=0;i<st.hazards.length;i++){
      const h = st.hazards[i];
      if(!h.alive) continue;
      if(H.rectsOverlap(pr, box(h))){
        h.alive = false;
        if(p.inv <= 0){
          p.hovers = Math.max(1, p.hovers - 1);
          p.inv = 1.0;
          p.vy -= 42;
          addBurst(st, h.x, h.y, '#fc54fc', 10);
          emit(ctx, 'pop', { source:'bomb' });
        }
      }
    }
    for(let i=0;i<st.enemies.length;i++){
      const e = st.enemies[i];
      if(!e.alive) continue;
      if(H.rectsOverlap(pr, box(e))){
        if(p.vy > e.vy || p.y < e.y - 5){
          e.hovers--;
          e.hit = 1;
          p.vy = -72;
          st.score += 100;
          emit(ctx, 'enemyBounced', { x:e.x, y:e.y });
          addBurst(st, e.x, e.y - 8, e.col, 8);
          if(e.hovers <= 0){
            e.alive = false;
            emit(ctx, 'enemyDestroyed', { x:e.x, y:e.y, score:st.score });
          }
        } else {
          p.vx += e.x < p.x ? 34 : -34;
          e.vx *= -1;
          if(p.inv <= 0){ p.inv = 0.8; p.hovers = Math.max(1, p.hovers - 0.5); }
        }
      }
    }
  }
  function make(area, unit, variant){
    const seed = 'hover:' + (variant || 0);
    const st = {
      pack:'hover',
      mode:'trip',
      nativeW:viewportWidth(area),
      nativeH:HGT,
      v:variant ? 1 : 0,
      seed,
      rng:H.rng(seed),
      nextId:1,
      t:0,
      stage:1,
      score:0,
      lives:3,
      waterY:178,
      worldX:0,
      cameraX:0,
      frontier:0,
      stageLength:2400,
      clusterIndex:0,
      player:{ type:'player', x:64, y:70, w:13, h:22, vx:0, vy:0, face:1, hovers:2, inv:0, flap:0, state:'fly', flapGap:0 },
      platforms:[],
      enemies:[],
      collectibles:[],
      hazards:[],
      effects:[],
      stars:[],
      fish:null,
      intent:{ steer:0, flap:false, target:null },
      music:{ bpm:132, energy:0.35, leadEnergy:0, counterEnergy:0, percEnergy:0, bass:0, beat:0, leadHi:0.5 },
      entities:[],
      watchdog: { meaningfulProgress:true }
    };
    spawnStars(st);
    if(variant) setupTrip(st);
    else setupFight(st);
    return st;
  }
  function update(ctx){
    const st = ctx.state;
    if(!st || st.pack !== 'hover') return;
    configureLayout(st, ctx.A);
    const dt = clamp(ctx.dt || 0, 0, 0.05);
    if(dt <= 0) return;
    st.t += dt;
    updateEffects(st, dt);
    if(ctx.audio && ctx.audio.paused){
      st.player.flap = Math.max(0, st.player.flap - dt * 4);
      return;
    }
    playerPhysics(ctx, dt);
    if(st.mode === 'trip') updateTrip(ctx, dt);
    else updateFight(ctx, dt);
    updateFish(ctx, dt);
    collisions(ctx);
  }

  const HoverDefinition = {
    packVersion:2,
    entities:['player','enemyHoverist','collectibleHover','bomb','fish','water','platform','star','particle'],
    events:['flap','hoverCollected','enemyBounced','enemyDestroyed','fishLunged','splash','pop','levelComplete'],
    manifest:{
      key:'hover',
      name:'HOVER FIGHT',
      version:2,
      scene:'aerial hover chase and trip',
      entities:['player','enemyHoverist','collectibleHover','bomb','fish','water','platform','star','particle'],
      events:['flap','hoverCollected','enemyBounced','enemyDestroyed','fishLunged','splash','pop','levelComplete']
    },
    watchdog:{ mode:'scroll', progress:26, motion:12, loop:12 },
    make,
    update,
    rules:{ update:function(){} },
    spawnTripCluster,
    configureLayout,
    resetPlayer
  };

  VisualizerGame.layer('hover', 'definition', HoverDefinition);
  rootObj().HoverDefinition = HoverDefinition;
})();

/* ===== packs/games/hover/behavior.js ===== */
// HOVER FIGHT autonomous behavior. Chooses intent; does not draw or mutate rules.
(function(){
  const H = VisualizerGame.helpers;

  function clamp(v, lo, hi){ return H.clamp(v, lo, hi); }
  function nearestCollectible(st, p){
    let best = null, bestScore = 1e9;
    const cam = st.cameraX || 0;
    for(let i=0;i<st.collectibles.length;i++){
      const b = st.collectibles[i];
      if(!b || b.got) continue;
      const dx = b.x - p.x;
      if(st.mode === 'trip' && dx < -20) continue;
      const dy = b.y - p.y;
      const forwardBias = st.mode === 'trip' ? Math.max(0, -dx) * 8 : 0;
      const score = Math.abs(dx) * 1.1 + Math.abs(dy) * 1.8 + forwardBias - (b.strength || 0) * 18;
      if(score < bestScore){ bestScore = score; best = b; }
    }
    if(best) return best;
    if(st.mode === 'fight'){
      for(let i=0;i<st.enemies.length;i++){
        const e = st.enemies[i];
        if(!e || !e.alive) continue;
        const score = Math.abs(e.x - p.x) + Math.abs(e.y - p.y) * 1.3;
        if(score < bestScore){ bestScore = score; best = { x:e.x, y:e.y - 16, hunt:true }; }
      }
    }
    return best;
  }
  function dangerPush(st, p){
    let pushX = 0, pushY = 0, danger = 0;
    const scan = st.hazards || [];
    for(let i=0;i<scan.length;i++){
      const h = scan[i];
      if(!h || !h.alive) continue;
      const dx = h.x - p.x, dy = h.y - p.y, d = Math.sqrt(dx*dx + dy*dy) || 1;
      if(d > 54) continue;
      const w = (54 - d) / 54;
      pushX -= dx / d * w;
      pushY -= dy / d * w;
      danger = Math.max(danger, w);
    }
    for(let i=0;i<st.enemies.length;i++){
      const e = st.enemies[i];
      if(!e || !e.alive) continue;
      const dx = e.x - p.x, dy = e.y - p.y, d = Math.sqrt(dx*dx + dy*dy) || 1;
      if(d > 42) continue;
      const w = (42 - d) / 42;
      pushX -= dx / d * w * 0.55;
      pushY -= dy / d * w * 0.35;
      danger = Math.max(danger, w * 0.7);
    }
    if(st.fish && st.fish.active){
      const fx = st.cameraX + st.fish.x;
      const dx = fx - p.x, dy = st.fish.y - p.y, d = Math.sqrt(dx*dx + dy*dy) || 1;
      if(d < 58){
        const w = (58 - d) / 58;
        pushX -= dx / d * w * 1.2;
        pushY -= dy / d * w * 0.8;
        danger = Math.max(danger, w);
      }
    }
    return { x:pushX, y:pushY, danger };
  }
  function manualIntent(ctx){
    const input = ctx.IN || {};
    return {
      steer:(input.right?1:0) - (input.left?1:0),
      flap:!!(input.up || input.action),
      target:null,
      manual:true,
      reason:'input'
    };
  }
  function update(ctx){
    const st = ctx.state;
    if(!st || st.pack !== 'hover' || !st.player) return;
    if(ctx.IN && ctx.IN.active){
      st.intent = manualIntent(ctx);
      return;
    }
    const p = st.player;
    const music = st.music || {};
    const target = nearestCollectible(st, p);
    const avoid = dangerPush(st, p);
    let goalX, goalY;
    if(target){
      goalX = target.x;
      goalY = target.y - (target.hunt ? 4 : 0);
    } else if(st.mode === 'trip'){
      goalX = st.cameraX + st.nativeW * 0.45 + Math.sin(st.t * 0.37) * 28;
      goalY = 82 + Math.sin(st.t * 0.6) * 30;
    } else {
      goalX = st.nativeW * 0.5 + Math.sin(st.t * 0.52) * Math.min(90, st.nativeW * 0.22);
      goalY = 80 + Math.sin(st.t * 0.7) * 34;
    }
    goalX += avoid.x * 42;
    goalY += avoid.y * 35;
    const safeTop = 24, safeBottom = st.waterY - 38;
    goalY = clamp(goalY, safeTop, safeBottom);
    let dx = goalX - p.x;
    let dy = goalY - p.y;
    let steer = clamp(dx / 46, -1, 1);
    if(st.mode === 'trip'){
      const leftBand = st.cameraX + 44;
      const rightBand = st.cameraX + st.nativeW - 84;
      if(p.x < leftBand) steer = Math.max(steer, 0.55);
      if(p.x > rightBand) steer = Math.min(steer, -0.45);
    }
    const altitudeUrgency = clamp((dy < 0 ? -dy / 34 : -dy / 70), -0.6, 1.1);
    const beatLift = (music.beat || 0) * 0.18 + (music.leadEnergy || 0) * 0.12;
    const flap = dy < -5 || avoid.danger > 0.62 || p.y > safeBottom - 8 || altitudeUrgency + beatLift > 0.55;
    st.intent = {
      steer,
      flap,
      target:target ? { x:target.x, y:target.y, type:target.type || (target.hunt ? 'enemy' : 'collectible') } : null,
      danger:avoid.danger,
      reason:target ? (target.hunt ? 'enemy' : 'collectible') : 'patrol'
    };
  }

  const HoverBehavior = {
    packVersion:2,
    key:'hover',
    goals:['collect hovers','avoid bombs','avoid fish','bounce enemies','stay readable on screen'],
    update
  };

  VisualizerGame.layer('hover', 'behavior', HoverBehavior);
  (typeof window !== 'undefined' ? window : globalThis).HoverBehavior = HoverBehavior;
})();

/* ===== packs/games/hover/reactions.js ===== */
// HOVER FIGHT audio reaction map. Normalized music bus in, render/behavior modifiers out.
(function(){
  const H = VisualizerGame.helpers;
  function clamp(v, lo, hi){ return H.clamp(v, lo, hi); }
  function roleEnergy(roles, name, fallback){
    const r = roles && roles[name];
    return clamp(r && r.energy != null ? r.energy : fallback || 0, 0, 1);
  }
  function roleHi(roles, name, fallback){
    const r = roles && roles[name];
    if(r && typeof r.hi === 'number') return clamp(r.hi, 0, 1);
    const notes = r && r.notes || [];
    if(notes.length && typeof MV !== 'undefined' && MV.noteHi) return MV.noteHi(notes[0]);
    return fallback == null ? 0.5 : fallback;
  }
  const bindings = [
    { system:'lead hovers', bus:'roles.lead.notes + roles.lead.energy', effect:'lead notes pick hover height, color pulse, and collection emphasis' },
    { system:'counter enemies', bus:'roles.counter.energy + roles.counter.notes', effect:'enemy flaps, separation, and hit pulse intensity' },
    { system:'bass water', bus:'roles.bass.energy + bands.bass', effect:'water waveform depth and fish tension' },
    { system:'perc bombs', bus:'roles.perc.onset + beatStrength', effect:'bomb bounce, warning pulse, and hazard spacing accents' },
    { system:'noise stars', bus:'roles.noise.energy + treble', effect:'star twinkle, foam, and sky detail' },
    { system:'world sky', bus:'barProgress + hue + energy', effect:'sky palette and cloud drift' },
    { system:'phrase stage', bus:'sectionChanged + phrase', effect:'readable cluster variation without changing hitboxes' },
    { system:'drop flock', bus:'drop + energy', effect:'short stage-wide visual lift and ordered hover emphasis' },
    { system:'idle float', bus:'paused + silence', effect:'hold progression but keep a restrained idle pose' }
  ];
  function apply(ctx){
    const st = ctx.state;
    if(!st || st.pack !== 'hover') return;
    const a = ctx.audio || {};
    const roles = a.roles || {};
    const leadEnergy = roleEnergy(roles, 'lead', a.energy * 0.7);
    const counterEnergy = roleEnergy(roles, 'counter', a.mid * 0.65);
    const bassEnergy = roleEnergy(roles, 'bass', a.bass);
    const percEnergy = roleEnergy(roles, 'perc', Math.max(a.beatStrength, a.bass * 0.6));
    const noiseEnergy = roleEnergy(roles, 'noise', a.treble);
    const leadHi = roleHi(roles, 'lead', a.treble * 0.6 + 0.2);
    const pulse = clamp(Math.max(a.beatStrength || 0, leadEnergy * 0.7), 0, 1);
    const drop = !!a.drop;
    st.music = {
      bpm:a.bpm || 132,
      energy:clamp(a.energy || 0, 0, 1),
      beat:pulse,
      beatHit:!!a.beat,
      leadEnergy,
      counterEnergy,
      bass:bassEnergy,
      percEnergy,
      noiseEnergy,
      leadHi,
      hue:a.hue || 0,
      barProgress:clamp(a.barProgress || 0, 0, 1),
      drop,
      paused:!!a.paused,
      idle:!!a.silence
    };
    const m = ctx.modifiers || {};
    m.paletteHue = st.music.hue;
    m.scalePulse = 0.02 + pulse * 0.11 + (drop ? 0.08 : 0);
    m.waterAmp = 2 + bassEnergy * 10 + a.energy * 5;
    m.waterFine = 1 + noiseEnergy * 4;
    m.skyLift = 0.04 + a.energy * 0.28;
    m.shake = drop ? 0.45 : clamp(bassEnergy * 0.18 + a.beatStrength * 0.06, 0, 0.25);
    m.trail = clamp(leadEnergy * 0.5 + noiseEnergy * 0.25, 0, 0.85);
    m.entityRoles = { lead:'collectibles', counter:'enemies', bass:'water', perc:'hazards', noise:'stars', world:'sky', phrase:'clusters', drop:'stagePulse', idle:'floatPose' };
    if(a.beat || pulse > 0.42){
      const cam = st.cameraX || 0;
      for(let i=0;i<st.collectibles.length;i++){
        const b = st.collectibles[i];
        if(!b.got && b.x > cam - 20 && b.x < cam + 290) b.pulse = Math.max(b.pulse || 0, pulse);
      }
      for(let i=0;i<st.hazards.length;i++){
        const h = st.hazards[i];
        if(h.alive && h.x > cam - 20 && h.x < cam + 290) h.pulse = Math.max(h.pulse || 0, percEnergy);
      }
      for(let i=0;i<st.enemies.length;i++){
        const e = st.enemies[i];
        if(e.alive) e.hit = Math.max(e.hit || 0, counterEnergy * 0.45);
      }
    }
    if(drop){
      st.dropPulse = 1;
      ctx.emit('dropPeak', { energy:st.music.energy, bpm:st.music.bpm });
    } else {
      st.dropPulse = Math.max(0, (st.dropPulse || 0) - (ctx.dt || 0) * 2.5);
    }
    st.entities.length = 0;
    st.entities.push({ role:'world', type:'sky', x:0, y:0, alive:true });
    st.entities.push({ role:'bass', type:'water', x:0, y:st.waterY, alive:true, energy:bassEnergy });
    for(let i=0;i<st.collectibles.length && st.entities.length<90;i++){
      const b = st.collectibles[i];
      if(b && !b.got) st.entities.push({ role:'lead', type:'collectibleHover', x:b.x, y:b.y, alive:true });
    }
    for(let i=0;i<st.hazards.length && st.entities.length<120;i++){
      const h = st.hazards[i];
      if(h && h.alive) st.entities.push({ role:'perc', type:'bomb', x:h.x, y:h.y, alive:true });
    }
    for(let i=0;i<st.enemies.length && st.entities.length<145;i++){
      const e = st.enemies[i];
      if(e && e.alive) st.entities.push({ role:'counter', type:'enemyHoverist', x:e.x, y:e.y, alive:true });
    }
    for(let i=0;i<Math.min(8, st.stars.length);i++){
      const s = st.stars[i];
      st.entities.push({ role:'noise', type:'star', x:s.x, y:s.y, alive:true });
    }
    if(st.dropPulse > 0 || a.beatStrength > 0.88) st.entities.push({ role:'drop', type:'stagePulse', x:st.player ? st.player.x : 0, y:st.player ? st.player.y : 0, alive:true });
    if(st.music.idle) st.entities.push({ role:'idle', type:'floatPose', x:st.player ? st.player.x : 0, y:st.player ? st.player.y : 0, alive:true });
    if(a.sectionChanged) ctx.emit('sectionChanged', { barProgress:st.music.barProgress, bpm:st.music.bpm });
  }

  const HoverReactions = {
    packVersion:2,
    key:'hover',
    entityRoles:{ lead:'collectibles', counter:'enemies', bass:'water', perc:'hazards', noise:'stars', world:'sky', phrase:'clusters', drop:'stagePulse', idle:'floatPose' },
    systems:{ lead:'collectibles', counter:'enemies', bass:'water', perc:'hazards', noise:'stars', world:'sky', phrase:'clusters', drop:'stagePulse', idle:'floatPose' },
    targets:{ leadTarget:'collectibles', counterTarget:'enemies', bassTarget:'water', percTarget:'hazards', noiseTarget:'stars', dropTarget:'stagePulse', idleTarget:'floatPose' },
    normalizedSignals:['beat','beatStrength','bass','mid','treble','energy','barProgress','sectionChanged','drop','silence','paused','bpm','roles'],
    bindings,
    apply
  };

  VisualizerGame.layer('hover', 'reactions', HoverReactions);
  (typeof window !== 'undefined' ? window : globalThis).HoverReactions = HoverReactions;
})();

/* ===== packs/games/hover/renderer.js ===== */
// HOVER FIGHT renderer. Draws state plus transient modifiers; owns no rules.
(function(){
  const CLOUD = [
    '..wwww..',
    '.wwwwww.',
    'wwwwwwww',
    '.wwwwww.',
    '..w..w..'
  ];
  // PLAYER: a helmeted hero (gold dome + white visor + orange suit + green boots).
  // Deliberately distinct in both silhouette and palette from the bare-headed,
  // red/blue ENEMY sprite below so a viewer instantly reads which one is the player.
  // The head block (rows 0-3) is IDENTICAL in every frame: only the arms and legs move, so the
  // animation never blurs the helmet+visor silhouette that makes him readable against the enemies.
  // One wing-beat = PLAYER_FLAP[0] (arms driven down, the power stroke) -> [1] (arms out, mid) ->
  // [2] (arms up, recovery). Legs stay APART through the beat.
  const PLAYER_FLAP = [
    [ // 0: down-stroke — hands driven below the shoulders
      '..hhhh..',
      '.hhhhhh.',
      '.hssssh.',
      '..ffff..',
      '.oossoo.',
      'o.oooo.o',
      '..oooo..',
      '..g..g..'
    ],
    [ // 1: mid — arms straight out (the original single static pose)
      '..hhhh..',
      '.hhhhhh.',
      '.hssssh.',
      '..ffff..',
      '.oossoo.',
      'oooooooo',
      '..oooo..',
      '..g..g..'
    ],
    [ // 2: up — hands raised beside the helmet, ready for the next beat
      '..hhhh..',
      '.hhhhhh.',
      'ohssssho',
      'o.ffff.o',
      '.oossoo.',
      '..oooo..',
      '..oooo..',
      '..g..g..'
    ]
  ];
  // Glide/sink: arms angled down in a V and — the tell — legs TOGETHER, so a falling hero reads
  // instantly differently from a flapping one even at broadcast scale.
  const PLAYER_GLIDE = [
    '..hhhh..',
    '.hhhhhh.',
    '.hssssh.',
    '..ffff..',
    '.oossoo.',
    '.oooooo.',
    'o.oooo.o',
    '...gg...'
  ];
  // Row the lean shear pivots around (waist): rows above it lead the turn, boots trail behind.
  const LEAN_PIVOT = 4;
  // Enemies get a light 2-frame arm tuck so the sky feels alive, but nothing about their
  // bare-headed red/blue read changes — the player stays the distinct one.
  const ENEMY_FLAP = [
    [
      '..f..f..',
      '..ffff..',
      '.fkkkkf.',
      '..ssss..',
      '.yyyyy.',
      'yypppyy',
      '..p.p..'
    ],
    [
      '..f..f..',
      '..ffff..',
      '.fkkkkf.',
      '..ssss..',
      '.yyyyy.',
      '.ypppy.',
      '.p...p.'
    ]
  ];
  const FISH = [
    '..rrrr..',
    '.rrrrrr.',
    'rrwrrrtr',
    '.rrrrrr.',
    '..r..r..'
  ];
  const HOVER = [
    '..cccc..',
    '.cccccc.',
    'cccccccc',
    'cccccccc',
    '.cccccc.',
    '..cccc..',
    '...ss...',
    '...ss...'
  ];
  const BOMB = [
    '..xx..',
    '.xkkx.',
    'xkkkkx',
    'xkkkkx',
    '.xkkx.',
    '..xx..'
  ];
  function clamp(v, lo, hi){ return VisualizerGame.clamp(v, lo, hi); }
  // `lean` shears the sprite by whole pixels per row (head leads, boots trail) for a pixel-grid tilt.
  // It is applied in SCREEN space, after the mirror, so the lean always follows the direction of
  // travel regardless of `flip`. Zero lean + no flip keeps the fast pix() path.
  function drawSprite(rows, map, tx, ty, px, flip, lean){
    const sh = lean || 0;
    if(!flip && !sh) return pix(rows, tx, ty, px, map);
    const cw = Math.ceil(px);
    for(let j=0;j<rows.length;j++){
      const r = rows[j];
      const ry = Math.round(ty + j * px);
      const rx = sh ? tx + Math.round(sh * (LEAN_PIVOT - j)) * px : tx;
      for(let i=0;i<r.length;i++){
        const c = map[flip ? r[r.length - 1 - i] : r[i]];
        if(!c) continue;
        g.fillStyle = c;
        g.fillRect(Math.round(rx + i * px), ry, cw, cw);
      }
    }
  }
  // Which body frame the player wears this tick. Driven by his OWN motion, never a free timer:
  // definition.js snaps p.flap to 1 the instant he flaps and decays it at 6/s, so (1 - p.flap) is
  // the normalised progress through one wing-beat and the arms therefore beat in time with the
  // actual flapping. With the beat spent he either glides (sinking) or holds the arms-up pose.
  function playerRows(p){
    if(p.flap > 0.02){
      const k = 1 - p.flap;
      return PLAYER_FLAP[k < 0.34 ? 0 : k < 0.67 ? 1 : 2];
    }
    return p.vy > 6 ? PLAYER_GLIDE : PLAYER_FLAP[2];
  }
  function render(ctx){
    const st = ctx.state, A = ctx.A, m = ctx.modifiers || {};
    if(!st || st.pack !== 'hover' || !A) return;
    const nw = st.nativeW || 256, nh = st.nativeH || 224;
    const scale = Math.min(A.w / nw, A.h / nh);
    const ox0 = A.x + (A.w - nw * scale) * 0.5;
    const oy0 = A.y + (A.h - nh * scale) * 0.5;
    const shake = m.shake || 0;
    const ox = ox0 + (Math.random() * 2 - 1) * 3 * shake;
    const oy = oy0 + (Math.random() * 2 - 1) * 3 * shake;
    const cam = st.mode === 'trip' ? st.cameraX : 0;
    const sx = x => ox + (x - cam) * scale;
    const sy = y => oy + y * scale;
    const sc = v => v * scale;
    const px = Math.max(1, Math.round(scale));
    const hue = m.paletteHue || 0;
    const skyTop = hueRot('#68d8f0', hue * 0.35);
    const skyBot = hueRot('#f0b8d8', hue * 0.28);
    const grad = g.createLinearGradient(0, A.y, 0, A.y + A.h);
    grad.addColorStop(0, skyTop);
    grad.addColorStop(0.75, skyBot);
    grad.addColorStop(1, '#06142b');
    g.fillStyle = grad;
    g.fillRect(A.x, A.y, A.w, A.h);

    g.globalAlpha = 0.22;
    for(let i=0;i<st.stars.length;i++){
      const s = st.stars[i];
      const tw = 0.35 + Math.sin(st.t * s.twinkle + s.phase) * 0.25 + (st.music ? st.music.noiseEnergy : 0) * 0.35;
      g.fillStyle = '#ffffff';
      g.fillRect(sx(cam + ((s.x - cam * (0.12 + i % 3 * 0.04)) % nw + nw) % nw), sy(s.y), Math.max(1, sc(s.size * tw)), Math.max(1, sc(s.size * tw)));
    }
    g.globalAlpha = 1;

    const cloudCount = Math.ceil(nw / 72) + 2;
    for(let c=-1;c<cloudCount;c++){
      const cx = cam * 0.28 + c * 72 + 22;
      const cy = 26 + (c % 3) * 18 + Math.sin(st.t * 0.4 + c) * 2;
      // Background scenery on the light shades only. A one-colour cloud ranked
      // like a sprite becomes INK -- as heavy on screen as a hazard.
      var _PDC=(typeof CT_PAL!=='undefined')&&CT_PAL;
      var _cmap={ w:'#ffffff', '.':null };
      if(_PDC&&_PDC.installed) _cmap=_PDC.decorMap(_cmap);
      drawSprite(CLOUD, _cmap, sx(cx - 8), sy(cy), px, false);
    }

    for(let i=0;i<st.platforms.length;i++){
      const p = st.platforms[i];
      g.fillStyle = hueRot('#b8f8d8', hue * 0.2);
      g.fillRect(sx(p.x - p.w / 2), sy(p.y), sc(p.w), sc(5));
      g.fillStyle = 'rgba(0,80,50,.28)';
      g.fillRect(sx(p.x - p.w / 2), sy(p.y + 5), sc(p.w), sc(4));
    }

    for(let i=0;i<st.collectibles.length;i++){
      const b = st.collectibles[i];
      if(b.got || b.x < cam - 30 || b.x > cam + nw + 40) continue;
      const pulse = 1 + (b.pulse || 0) * 0.16 + (m.scalePulse || 0) * 0.5;
      const col = hueRot(b.col || '#54fc54', hue * 0.45 + (b.pitch || 0) * 80);
      g.save();
      g.translate(sx(b.x), sy(b.y));
      g.scale(pulse, pulse);
      drawSprite(HOVER, { c:col, s:'#b8b8c8', k:'#101018', x:'#ffffff', '.':null }, -4 * px, -7 * px, px, false);
      g.restore();
    }

    for(let i=0;i<st.hazards.length;i++){
      const h = st.hazards[i];
      if(!h.alive || h.x < cam - 30 || h.x > cam + nw + 40) continue;
      const pulse = 1 + (h.pulse || 0) * 0.18;
      g.save();
      g.translate(sx(h.x), sy(h.y));
      g.scale(pulse, pulse);
      drawSprite(BOMB, { k:'#1b1028', x:hueRot('#fc54fc', hue), '.':null }, -3 * px, -3 * px, px, false);
      g.restore();
    }

    for(let i=0;i<st.enemies.length;i++){
      const e = st.enemies[i];
      if(!e.alive) continue;
      const pulse = 1 + (e.hit || 0) * 0.18 + (st.music ? st.music.counterEnergy * 0.04 : 0);
      const flip = e.face < 0;
      for(let b=0;b<Math.max(1, e.hovers);b++){
        const bx = e.x + (b - 0.5) * 8;
        const by = e.y - 17 + Math.sin(st.t * 4 + e.phase + b) * 2;
        // NOT hue-rotated: e.col comes from the green-free ENEMY_HOVER_COLORS pool, and rotating it would sweep
        // some enemies straight through green — defeating the whole point of reserving green for the player.
        drawSprite(HOVER, { c:e.col, s:'#c8c8d8', '.':null }, sx(bx - 4), sy(by - 7), px, false);
      }
      g.save();
      g.translate(sx(e.x), sy(e.y));
      g.scale(pulse, pulse);
      // e.phase already advances every frame in updateFight (dt * 3), so the tuck cycles with the
      // enemy's own bob — deterministic, no timer of its own.
      drawSprite(ENEMY_FLAP[Math.sin(e.phase * 2) > 0 ? 0 : 1], { f:'#f0c090', k:'#101018', s:'#ffffff', y:'#fc5454', p:'#3c3cfc', '.':null }, -4 * px, -2 * px, px, flip);
      g.restore();
    }

    const p = st.player;
    const invAlpha = p.inv > 0 ? 0.55 + Math.sin(st.t * 36) * 0.25 : 1;
    g.globalAlpha = clamp(invAlpha, 0.25, 1);
    const bCount = Math.max(1, Math.round(p.hovers));
    // '#54fc54' (green) is the player's RESERVED hover color; enemy hovers draw from ENEMY_HOVER_COLORS
    // (definition.js), which excludes green. Both sides are drawn UNROTATED — hue-rotating them (as this used to)
    // slid the player off green and swept enemies onto it, so the player became impossible to pick out.
    for(let b=0;b<bCount;b++){
      const bx = p.x + (b - (bCount - 1) / 2) * 8;
      const by = p.y - 22 + Math.sin(st.t * 4.5 + b) * 1.8;
      drawSprite(HOVER, { c:'#54fc54', s:'#e8ffe8', '.':null }, sx(bx - 4), sy(by - 7), px, false);
    }
    const playerFlip = p.vx < -1;
    // Lean: a sub-sprite tilt straight off p.vx (which physics clamps to [-54, 68]), on top of the
    // existing flip. Small enough to read as body English, never as a new silhouette.
    const playerLean = clamp(p.vx / 150, -0.3, 0.3);
    // Balloon Kid's silhouette is the BALLOONS, not the figure: two rounded
    // shapes above the head on short strings, which is what makes the sprite
    // readable at Game Boy size and from across a room. Ours was a bare flapping
    // figure -- the Balloon Fight design -- and at 144 rows it read as a smudge.
    // Drawn above the body so the body art and its animation are untouched.
    if(typeof CT_DMG_NATIVE !== 'undefined' && CT_DMG_NATIVE){
      // Whole-pixel sway. A fractional offset lands the sprite between LCD
      // cells and the rounding flips every frame, which reads as a flicker.
      var bsway = Math.round(Math.sin(st.t * 2.6 + p.x * 0.05)) * px;
      drawSprite([
        '.OO..OO.',
        'OOOOOOOO',
        'OOOOOOOO',
        '.OO..OO.',
        '..o..o..',
        '...oo...'
      ], { O:'#ffffff', o:'#101010', '.':null },
        sx(p.x - 4) + bsway, sy(p.y - 2 - p.flap * 2) - px * 6, px, false, 0);
    }
    // The PLAYER. Five colours ranked by luminance gave a mid-shade speckle with
    // limbs and helmet all the same weight -- an insect, not a character. Ink
    // outline, solid body, white highlight, and drawn larger.
    var _PHV=(typeof CT_PAL!=='undefined')&&CT_PAL, _hv=_PHV&&_PHV.installed;
    var _pmap={ h:'#ffcc33', s:'#ffffff', f:'#f0c090', o:'#ff7a1a', g:'#54fc54', '.':null };
    if(_hv) _pmap=_PHV.heroMap(_pmap);
    drawSprite(playerRows(p), _pmap, sx(p.x - 4), sy(p.y - 2 - p.flap * 2), _hv?Math.round(px*1.4):px, playerFlip, playerLean);
    g.globalAlpha = 1;

    if(st.fish && st.fish.active){
      drawSprite(FISH, { r:'#fc5454', w:'#ffffff', t:'#54fcfc', '.':null }, sx(st.cameraX + st.fish.x - 4), sy(st.fish.y - 4), px, false);
    }

    for(let i=0;i<st.effects.length;i++){
      const e = st.effects[i];
      const a = 1 - e.age / e.ttl;
      g.globalAlpha = clamp(a, 0, 1);
      g.fillStyle = hueRot(e.col, hue * 0.35);
      g.fillRect(sx(e.x), sy(e.y), Math.max(1, sc(e.size)), Math.max(1, sc(e.size)));
    }
    g.globalAlpha = 1;

    const waterY = st.waterY;
    const amp = m.waterAmp || 4;
    const fine = m.waterFine || 1;
    g.beginPath();
    g.moveTo(A.x, sy(waterY));
    for(let i=0;i<=96;i++){
      const x = cam + i / 96 * nw;
      const wv = Math.sin(x * 0.055 + st.t * 2.8) * amp * 0.45 +
        Math.sin(x * 0.14 - st.t * 3.8) * fine +
        Math.sin(i * 0.9 + (st.music ? st.music.barProgress * Math.PI * 2 : 0)) * amp * 0.18;
      g.lineTo(sx(x), sy(waterY + wv));
    }
    g.lineTo(A.x + A.w, A.y + A.h);
    g.lineTo(A.x, A.y + A.h);
    g.closePath();
    g.fillStyle = hueRot('#0068b8', hue * 0.16);
    g.fill();
    g.strokeStyle = hueRot('#fca044', hue * 0.3);
    g.lineWidth = Math.max(1, scale * 0.5);
    g.stroke();

    g.fillStyle = 'rgba(4,8,24,.28)';
    for(let y=A.y;y<A.y+A.h;y+=Math.max(2, Math.round(scale * 0.65))){
      g.fillRect(A.x, y, A.w, 1);
    }
  }

  const HoverRenderer = {
    packVersion:2,
    key:'hover',
    adapter:'custom-canvas-pack',
    performance:{ oneActiveLoop:true, ownsAnimationLoop:false, usesReactStatePerFrame:false, maxEntities:220, maxParticles:96, maxEventsPerFrame:64 },
    render,
    dispose:function(ctx){
      if(ctx && ctx.state && ctx.state.$viz) ctx.state.$viz.disposed = true;
    }
  };

  VisualizerGame.layer('hover', 'renderer', HoverRenderer);
  (typeof window !== 'undefined' ? window : globalThis).HoverRenderer = HoverRenderer;
})();

