    var cameraAnchor=Math.min(86,Math.max(24,st.nativeW*.34));
    st.cameraX+=((h.x-cameraAnchor)-st.cameraX)*Math.min(1,dt*4.8);if(st.cameraX<0)st.cameraX=0;
    var min=st.cameraX-116;
