  const DOOR_COLORS = ['#ffb8ae','#ffb8ff','#b8fff8','#ffe0b8','#e8c8ff','#c8ffd8','#ffd0d8','#fff4c0'];
  const DOT_COLORS = ['#ffb8ae','#ffd8f8','#b8fff8','#ffe0b8'];
