        if(sent&&typeof sent.then==='function') sent.then(function(){ _lastNp=k; if(_pendingNp===k)_pendingNp=''; },function(e){ if(_pendingNp===k)_pendingNp=''; console.error('[desktop] now-playing report failed:',e); });
